/// <reference types="svelte" />
/**
 * Store: rocket — Team Rocket panel
 */

import { facade } from '@bus/facade';
import { GameEventType as Evt } from '../bus/events.js';
import type { RocketSnapshot, RocketRealtimeSnapshot, RocketContractModalSnapshot } from '../bus/snapshots.js';
import { EMPTY_ROCKET_SNAPSHOT, EMPTY_ROCKET_REALTIME } from '../lib/rocketSnapshotBuilder.js';
import { EMPTY_ROCKET_CASINO_MODAL } from '../lib/rocketCasinoSnapshot.js';

class RocketStore {
  snapshot: RocketSnapshot = $state(EMPTY_ROCKET_SNAPSHOT);
  realtime: RocketRealtimeSnapshot = $state(EMPTY_ROCKET_REALTIME);
  casinoModal = $state(EMPTY_ROCKET_CASINO_MODAL);
  contractModal: RocketContractModalSnapshot | null = $state(null);
}

export const rocket = new RocketStore();

facade.subscribe(Evt.ROCKET_CHANGED, (evt) => {
  if (!('rocket' in evt)) return;
  rocket.snapshot = evt.rocket;
});

facade.subscribe(Evt.ROCKET_TICK, (evt) => {
  if (!('realtime' in evt)) return;
  rocket.realtime = evt.realtime;
});

facade.subscribe(Evt.ROCKET_CASINO_CHANGED, (evt) => {
  if (!('casinoModal' in evt)) return;
  rocket.casinoModal = evt.casinoModal;
});

facade.subscribe(Evt.ROCKET_CONTRACT_CHANGED, (evt) => {
  if (!('contractModal' in evt)) return;
  rocket.contractModal = evt.contractModal;
});
